class R2 { objects=new Map(); uploaded=new Map(); failPut=false; failDelete=false; failDeleteCount=0; onPut=null; async put(k,v){if(this.failPut)throw Error('r2 put failed');this.objects.set(k,new Uint8Array(await new Response(v).arrayBuffer()));this.uploaded.set(k,new Date());await this.onPut?.(k)} async get(k){const v=this.objects.get(k);return v&&{body:v}} async delete(k){if(this.failDelete||this.failDeleteCount-->0)throw Error('r2 delete failed');this.objects.delete(k);this.uploaded.delete(k)} async list(){return{objects:[...this.objects].map(([key,value])=>({key,size:value.byteLength,uploaded:this.uploaded.get(key)||new Date(0)})),truncated:false}} }
