 r=await call(e,'/api/attachments/attach_123/metadata',{method:'PUT',body:{version:1,iv:'new',ciphertext:'cipher',revision:1},headers:h});assert.equal(r.status,200);assert.equal((await r.json()).revision,2);r=await call(e,'/api/attachments/attach_123/metadata',{method:'PUT',body:{version:1,iv:'stale',ciphertext:'stale',revision:1},headers:h});assert.equal(r.status,409);assert.deepEqual(await r.json(),{error:'conflict',currentRevision:2});assert.equal((await call(e,'/api/attachments/attach_123',{method:'DELETE',headers:{...h,'x-csrf-token':'bad','if-match':'2'}})).status,403);
