test('真实 Miniflare D1 验证条目和附件 CAS、tombstone 后继 revision 与 batch 回滚',async()=>{const mf=new Miniflare({modules:true,compatibilityDate:'2026-07-11',d1Databases:['DB'],script:'export default {fetch(){return new Response("ok")}}'});try{const db=await mf.getD1Database('DB');await db.exec("PRAGMA foreign_keys=ON;CREATE TABLE users(id TEXT PRIMARY KEY);CREATE TABLE entries(user_id TEXT NOT NULL,id TEXT NOT NULL,type TEXT NOT NULL,version INTEGER NOT NULL,iv TEXT NOT NULL,ciphertext TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(user_id,id));CREATE TABLE attachments(user_id TEXT NOT NULL,id TEXT NOT NULL,metadata_iv TEXT NOT NULL,metadata_ciphertext TEXT NOT NULL,object_key TEXT NOT NULL UNIQUE,ciphertext_size INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(user_id,id));CREATE TABLE backup_import_locks(user_id TEXT PRIMARY KEY,token TEXT NOT NULL,expires_at INTEGER NOT NULL);CREATE TABLE pending_r2_deletions(object_key TEXT PRIMARY KEY,ciphertext_size INTEGER NOT NULL,created_at INTEGER NOT NULL);CREATE TABLE revision_tombstones(user_id TEXT NOT NULL,resource_type TEXT NOT NULL CHECK(resource_type IN('entry','attachment')),id TEXT NOT NULL,last_revision INTEGER NOT NULL CHECK(last_revision>=1),PRIMARY KEY(user_id,resource_type,id));INSERT INTO users VALUES('u');INSERT INTO entries VALUES('u','entry_aba','note',1,'iv','old',1,1,1);INSERT INTO attachments VALUES('u','attach_aba','iv','cipher','object-old',16,1,1,1);");let result=await db.prepare('UPDATE entries SET ciphertext=?,revision=revision+1 WHERE user_id=? AND id=? AND revision=?').bind('new','u','entry_aba',1).run();assert.equal(result.meta.changes,1);result=await db.prepare('UPDATE entries SET ciphertext=?,revision=revision+1 WHERE user_id=? AND id=? AND revision=?').bind('stale','u','entry_aba',1).run();assert.equal(result.meta.changes,0);let batch=await db.batch([db.prepare('DELETE FROM entries WHERE user_id=? AND id=? AND revision=?').bind('u','entry_aba',2),db.prepare("INSERT INTO revision_tombstones(user_id,resource_type,id,last_revision) SELECT ?,'entry',?,? WHERE changes()=1").bind('u','entry_aba',2)]);assert.equal(batch[0].meta.changes,1);await db.prepare("INSERT INTO entries(user_id,id,type,version,iv,ciphertext,created_at,updated_at,revision) SELECT ?,?,?,?,?,?,?,?,COALESCE((SELECT last_revision+1 FROM revision_tombstones WHERE user_id=? AND resource_type='entry' AND id=?),1)").bind('u','entry_aba','note',1,'iv','rebuilt',2,2,'u','entry_aba').run();assert.equal((await db.prepare("SELECT revision,ciphertext FROM entries WHERE id='entry_aba'").first()).revision,3);assert.equal((await db.prepare("UPDATE entries SET ciphertext='aba' WHERE user_id='u' AND id='entry_aba' AND revision=2").run()).meta.changes,0);batch=await db.batch([db.prepare('DELETE FROM attachments WHERE user_id=? AND id=? AND revision=?').bind('u','attach_aba',1),db.prepare("INSERT INTO revision_tombstones(user_id,resource_type,id,last_revision) SELECT ?,'attachment',?,? WHERE changes()=1").bind('u','attach_aba',1),db.prepare('INSERT INTO pending_r2_deletions(object_key,ciphertext_size,created_at) SELECT ?,?,? WHERE changes()=1').bind('object-old',16,2)]);assert.deepEqual(batch.map(x=>x.meta.changes),[1,1,1]);assert.equal((await db.prepare("SELECT last_revision FROM revision_tombstones WHERE resource_type='attachment' AND id='attach_aba'").first()).last_revision,1);await assert.rejects(db.batch([db.prepare("INSERT INTO entries VALUES('u','rollback1','note',1,'iv','x',1,1,1)"),db.prepare("INSERT INTO entries VALUES('u','rollback1','note',1,'iv','x',1,1,1)")]));assert.equal((await db.prepare("SELECT COUNT(*) AS count FROM entries WHERE id='rollback1'").first()).count,0)}finally{await mf.dispose()}});

test('真实 Miniflare D1 备份锁仅允许过期记录原子接管',async()=>{const mf=new Miniflare({modules:true,compatibilityDate:'2026-07-11',d1Databases:['DB'],script:'export default {fetch(){return new Response("ok")}}'});try{const db=await mf.getD1Database('DB');await db.exec('CREATE TABLE backup_import_locks(user_id TEXT PRIMARY KEY,token TEXT NOT NULL,expires_at INTEGER NOT NULL)');const acquire=async(token,now)=>await db.prepare('INSERT INTO backup_import_locks(user_id,token,expires_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET token=excluded.token,expires_at=excluded.expires_at WHERE backup_import_locks.expires_at<=?').bind('user',token,now+600_000,now).run();let result=await acquire('first',1000);assert.equal(result.meta.changes,1);result=await acquire('blocked',2000);assert.equal(result.meta.changes,0);assert.equal((await db.prepare('SELECT token FROM backup_import_locks WHERE user_id=?').bind('user').first()).token,'first');result=await acquire('replacement',700_000);assert.equal(result.meta.changes,1);assert.equal((await db.prepare('SELECT token FROM backup_import_locks WHERE user_id=?').bind('user').first()).token,'replacement')}finally{await mf.dispose()}});

test('真实 Miniflare D1 仅在CAS成功时创建会话并删除本请求限速槽',async()=>{const mf=new Miniflare({modules:true,compatibilityDate:'2026-07-11',d1Databases:['DB'],script:`export default {async fetch(req,env){const {mode}=await req.json(),slot=mode==='winner'?1:2,old=mode==='winner'?0:99;await env.DB.prepare('INSERT INTO login_attempts VALUES(?,?)').bind('passkey:ip',slot).run();const results=await env.DB.batch([env.DB.prepare('UPDATE credential SET counter=1 WHERE id=1 AND counter=?').bind(old),env.DB.prepare("INSERT INTO sessions(id) SELECT ? WHERE changes()=1").bind(mode),env.DB.prepare('DELETE FROM login_attempts WHERE key=? AND attempted_at=? AND changes()=1').bind('passkey:ip',slot)]);return Response.json(results.map(x=>x.meta.changes))}}`});try{const db=await mf.getD1Database('DB');await db.exec('CREATE TABLE credential(id INTEGER PRIMARY KEY,counter INTEGER);CREATE TABLE sessions(id TEXT);CREATE TABLE login_attempts(key TEXT,attempted_at REAL);INSERT INTO credential VALUES(1,0);');let r=await mf.dispatchFetch('https://vault.test/',{method:'POST',body:JSON.stringify({mode:'winner'})});assert.deepEqual(await r.json(),[1,1,1]);r=await mf.dispatchFetch('https://vault.test/',{method:'POST',body:JSON.stringify({mode:'stale'})});assert.deepEqual(await r.json(),[0,0,0]);assert.deepEqual((await db.prepare('SELECT id FROM sessions').all()).results,[{id:'winner'}]);assert.deepEqual((await db.prepare('SELECT attempted_at FROM login_attempts').all()).results,[{attempted_at:2}])}finally{await mf.dispose()}});
test('真实 Miniflare R2 接受固定长度二进制值',async()=>{const mf=new Miniflare({modules:true,compatibilityDate:'2026-07-11',r2Buckets:['ATTACHMENTS'],script:`export default {async fetch(req,env){const bytes=await req.arrayBuffer();const object=await env.ATTACHMENTS.put('probe',bytes);return new Response(String(object.size))}}`});try{const r=await mf.dispatchFetch('https://vault.test/upload',{method:'POST',headers:{'content-length':'16'},body:new Uint8Array(16)});assert.equal(r.status,200);assert.equal(await r.text(),'16')}finally{await mf.dispose()}});
