test('真实Miniflare D1并发清理队列只释放一次配额',async()=>{const mf=new Miniflare({modules:true,compatibilityDate:'2026-07-11',d1Databases:['DB'],script:`export default {async fetch(req,env){const key='orphan',size=16;await env.DB.batch([env.DB.prepare('DELETE FROM pending_r2_deletions WHERE object_key=?').bind(key),env.DB.prepare('UPDATE r2_storage_usage SET reserved_bytes=reserved_bytes-? WHERE id=1 AND changes()=1').bind(size)]);return new Response('ok')}}`});try{const db=await mf.getD1Database('DB');await db.exec('CREATE TABLE pending_r2_deletions(object_key TEXT PRIMARY KEY,ciphertext_size INTEGER,created_at INTEGER);CREATE TABLE r2_storage_usage(id INTEGER PRIMARY KEY,reserved_bytes INTEGER);INSERT INTO pending_r2_deletions VALUES(\'orphan\',16,1);INSERT INTO r2_storage_usage VALUES(1,16);');await Promise.all([mf.dispatchFetch('https://vault.test/'),mf.dispatchFetch('https://vault.test/')]);assert.deepEqual((await db.prepare('SELECT reserved_bytes FROM r2_storage_usage').first()),{reserved_bytes:0});assert.equal((await db.prepare('SELECT COUNT(*) AS count FROM pending_r2_deletions').first()).count,0)}finally{await mf.dispose()}});
test('Worker 认证请求顺便清理过期会话',async()=>{const e=env(),a=await login(e);e.DB.sessions.push({...e.DB.sessions[0],id_hash:'expired',expires_at:Date.now()-1});assert.equal((await call(e,'/api/session',{headers:{cookie:a.cookie}})).status,200);assert.equal(e.DB.sessions.some(x=>x.id_hash==='expired'),false)});
test('Worker 替换附件失败时释放新旧 storage 差值且保留旧附件',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf};await call(e,'/api/attachments/old_item1',{method:'POST',raw:new Uint8Array(16).fill(3),headers:{...h,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)}});const backup=await (await call(e,'/api/backup?attachments=1',{headers:{cookie:a.cookie}})).json();backup.attachments[0].object=btoa(String.fromCharCode(...new Uint8Array(20).fill(4)));backup.attachments[0].ciphertextSize=20;backup.attachments[0].sha256=await (async()=>{const b=await crypto.subtle.digest('SHA-256',new Uint8Array(20).fill(4));return Buffer.from(b).toString('base64url')})();
  e.DB.failReplaceBatch=true;const beforeA=e.DB.usage[0].class_a;assert.equal((await call(e,'/api/backup',{method:'PUT',body:backup,headers:h})).status,500);assert.equal(e.DB.storage,16);assert.equal(e.DB.attachments[0].id,'old_item1');assert.equal(e.ATTACHMENTS.objects.size,1);assert.equal(e.DB.usage[0].class_a,beforeA+1);
});
test('Worker 同一用户并发完整备份导入只允许一个替换事务',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf};await call(e,'/api/attachments/base_item',{method:'POST',raw:new Uint8Array(16).fill(3),headers:{...h,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)}});const backup=await (await call(e,'/api/backup?attachments=1',{headers:{cookie:a.cookie}})).json();let release;const blocked=new Promise(r=>release=r),entered=new Promise(r=>{e.ATTACHMENTS.onPut=async()=>{e.ATTACHMENTS.onPut=null;r();await blocked}});const first=call(e,'/api/backup',{method:'PUT',body:backup,headers:h});await entered;const second=await call(e,'/api/backup',{method:'PUT',body:backup,headers:h});assert.equal(second.status,409);release();assert.equal((await first).status,200);assert.equal(e.DB.backupLocks.length,0);assert.equal(e.DB.attachments.length,1)});
test('Worker 活跃完整导入续租后不得被第二个导入接管',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf};for(const id of ['base_lease1','base_lease2'])await call(e,'/api/attachments/'+id,{method:'POST',raw:new Uint8Array(16).fill(3),headers:{...h,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)}});const backup=await (await call(e,'/api/backup?attachments=1',{headers:{cookie:a.cookie}})).json();const realNow=Date.now;let now=realNow(),puts=0,release,entered;const blocked=new Promise(r=>release=r),seen=new Promise(r=>entered=r);Date.now=()=>now;e.ATTACHMENTS.onPut=async()=>{puts++;now+=9*60*1000;if(puts===2){entered();await blocked}};try{const first=call(e,'/api/backup',{method:'PUT',body:backup,headers:h});await seen;const second=await call(e,'/api/backup',{method:'PUT',body:backup,headers:h});assert.equal(second.status,409);release();assert.equal((await first).status,200)}finally{Date.now=realNow}});
test('Worker Scheduled通过R2 inventory发现未登记孤儿且配额不下溢',async()=>{for(const reserved of [19,0]){const e=env(),key='lost-orphan',size=19;e.ATTACHMENTS.objects.set(key,new Uint8Array(size));e.DB.storage=reserved;let pending;worker.scheduled?.({},e,{waitUntil(p){pending=p}});await pending;assert.equal(e.ATTACHMENTS.objects.has(key),false);assert.equal(e.DB.storage,0)}});
test('Worker Scheduled不得把R2写入与D1提交窗口中的新附件当孤儿删除',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)};let release,entered;const blocked=new Promise(r=>release=r),seen=new Promise(r=>entered=r);e.ATTACHMENTS.onPut=async()=>{entered();await blocked};const upload=call(e,'/api/attachments/raceitem',{method:'POST',raw:new Uint8Array(16),headers:h});await seen;let pending;worker.scheduled?.({},e,{waitUntil(p){pending=p}});await pending;release();assert.equal((await upload).status,201);assert.equal(e.ATTACHMENTS.objects.size,1);assert.equal(e.DB.attachments.length,1)});
test('Worker 清理前二次发现有效D1引用时仅移除错误pending',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)};await call(e,'/api/attachments/liveitem',{method:'POST',raw:new Uint8Array(16),headers:h});const key=e.DB.attachments[0].object_key;e.DB.pendingR2Deletes.push({object_key:key,ciphertext_size:16});await call(e,'/api/session',{headers:{cookie:a.cookie}});assert.equal(e.ATTACHMENTS.objects.has(key),true);assert.equal(e.DB.attachments.length,1);assert.equal(e.DB.pendingR2Deletes.length,0);assert.equal(e.DB.storage,16)});
test('Worker 未过期备份锁不可抢占，过期锁可由新导入原子接管',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf},backup=await (await call(e,'/api/backup?attachments=1',{headers:{cookie:a.cookie}})).json(),userId=e.DB.users[0].id;e.DB.backupLocks.push({user_id:userId,token:'running',expires_at:Date.now()+60_000});assert.equal((await call(e,'/api/backup',{method:'PUT',body:backup,headers:h})).status,409);assert.equal(e.DB.backupLocks[0].token,'running');e.DB.backupLocks[0].expires_at=Date.now()-1;assert.equal((await call(e,'/api/backup',{method:'PUT',body:backup,headers:h})).status,200);assert.equal(e.DB.backupLocks.length,0)});
test('Worker aged在途上传受inflight保护且随后正常提交',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)};let release,entered,key;const blocked=new Promise(r=>release=r),seen=new Promise(r=>entered=r);e.ATTACHMENTS.onPut=async k=>{key=k;e.ATTACHMENTS.uploaded.set(k,new Date(Date.now()-16*60*1000));entered();await blocked};const upload=call(e,'/api/attachments/agedrace',{method:'POST',raw:new Uint8Array(16),headers:h});await seen;let pending;worker.scheduled?.({},e,{waitUntil(p){pending=p}});await pending;release();assert.equal((await upload).status,201);assert.equal(e.DB.attachments.some(x=>x.object_key===key),true);assert.equal(e.ATTACHMENTS.objects.has(key),true);assert.equal(e.DB.inflight.length,0)});
test('Worker 备份锁所有权在R2写入后丢失时补偿新对象且保留旧资料与配额',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf};await call(e,'/api/attachments/base_lock',{method:'POST',raw:new Uint8Array(16),headers:{...h,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)}});const oldKey=e.DB.attachments[0].object_key,backup=await (await call(e,'/api/backup?attachments=1',{headers:{cookie:a.cookie}})).json();let release,entered,newKey;const blocked=new Promise(r=>release=r),seen=new Promise(r=>entered=r);e.ATTACHMENTS.onPut=async key=>{newKey=key;entered();await blocked};const old=call(e,'/api/backup',{method:'PUT',body:backup,headers:h});await seen;e.DB.backupLocks[0].token='new-owner';release();assert.equal((await old).status,500);assert.equal(e.DB.attachments[0].id,'base_lock');assert.equal(e.DB.attachments[0].object_key,oldKey);assert.equal(e.ATTACHMENTS.objects.has(oldKey),true);assert.equal(e.ATTACHMENTS.objects.has(newKey),false);assert.equal(e.DB.inflight.some(x=>x.object_key===newKey),false);assert.equal(e.DB.pendingR2Deletes.some(x=>x.object_key===newKey),false);assert.equal(e.DB.storage,16)});

test('Worker 专用补偿端点以旧sessionId和CSRF删除旧账户附件且不依赖当前cookie',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf};let r=await call(e,'/api/attachments/old_cleanup',{method:'POST',raw:new Uint8Array(16),headers:{...h,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)}}),created=await r.json();assert.equal(r.status,201);r=await call(e,'/api/attachments/old_cleanup/compensation',{method:'DELETE',headers:{origin:'https://vault.test','x-source-session-id':a.json.sessionId,'x-csrf-token':a.json.csrf,'if-match':String(created.revision)}});assert.equal(r.status,204);assert.equal(e.DB.attachments.some(x=>x.id==='old_cleanup'),false);assert.equal(e.ATTACHMENTS.objects.size,0);assert.equal(e.DB.storage,0)});

test('Worker 专用补偿端点拒绝伪造session与错误CSRF且不删除附件',async()=>{const e=env(),a=await login(e),h={cookie:a.cookie,origin:'https://vault.test','x-csrf-token':a.json.csrf};let r=await call(e,'/api/attachments/protected_cleanup',{method:'POST',raw:new Uint8Array(16),headers:{...h,'content-length':'16','x-attachment-metadata':JSON.stringify(metadata)}}),created=await r.json();for(const headers of [{'x-source-session-id':'forged-session-id','x-csrf-token':a.json.csrf},{'x-source-session-id':a.json.sessionId,'x-csrf-token':'wrong-csrf-token'}]){r=await call(e,'/api/attachments/protected_cleanup/compensation',{method:'DELETE',headers:{origin:'https://vault.test',...headers,'if-match':String(created.revision)}});assert.equal(r.status,401);assert.equal(e.DB.attachments.some(x=>x.id==='protected_cleanup'),true)}e.DB.sessions[0].expires_at=Date.now()-1;r=await call(e,'/api/attachments/protected_cleanup/compensation',{method:'DELETE',headers:{origin:'https://vault.test','x-source-session-id':a.json.sessionId,'x-csrf-token':a.json.csrf,'if-match':String(created.revision)}});assert.equal(r.status,401);assert.equal(e.DB.attachments.some(x=>x.id==='protected_cleanup'),true)});
